sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var task = new GlideRecord('x_snc_campus_foo_1_complain_tasks');

    task.addQuery('use_case_number', current.getValue('number'));
    task.query();

    if (task.next()) {
        task.student_count = current.getValue('student_count');
        task.update();
    }

})(current, previous);

